public sealed partial class CreditReminderSqlTests():CreditRequirementsSqlBase(new SqlFixture()),IAsyncLifetime
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private sealed record Scenario(HttpClient Customer,string Owner,string Order,string Variant,JsonNode OrderSummary,JsonNode[] Cheques);
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);private static string Base(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+s.Order;private static string Reminder(Scenario s,int index=0)=>Base(s)+"/cheques/"+V(s.Cheques[index],"id")+"/reminders";
    private static async Task<JsonNode> Read(HttpResponseMessage response)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: "+System.Text.RegularExpressions.Regex.Replace(raw,"(?i)Bearer [A-Za-z0-9._~-]+","Bearer [REDACTED-SYNTHETIC-QA-TOKEN]"));Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CREDIT_REMINDER_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var request=response.RequestMessage!;JsonNode? requestBody=request.Options.TryGetValue(new HttpRequestOptionsKey<string>("SyntheticReminderPostedBody"),out var posted)?JsonNode.Parse(posted):null;var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,requestBody}));}return JsonNode.Parse(raw)!;}
    }
    private async Task<Scenario> Ready(HttpClient f,HttpClient reviewer,bool commit=true)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(f,reviewer);var created=await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic reminder QA","09100000000",new("IR","تهران","تهران","Synthetic only; no actual person, delivery or funds","1234567890"),"Synthetic software QA only",true,true)));var summary=created["order"]!["summary"]!;var order=V(summary,"id");var path="/api/admin/credit/orders/"+s.Owner+"/"+order;var day=ChequeReportRules.Today(DateTimeOffset.UtcNow);var pi=new CreditSchedulePreviewInput(V(summary,"version"),null,"Gregorian",day);var preview=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/preview",pi));var schedule=(await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/commands/"+Id(),new SaveCreditScheduleInput(pi.OrderVersion,null,"Gregorian",day,V(preview,"fingerprint"),true))))["revision"]!;var cheques=new List<JsonNode>();foreach(var line in schedule["calculation"]!["lines"]!.AsArray()){var received=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/cheques/receive/commands/"+Id(),new ReceiveChequeInput(pi.OrderVersion,V(schedule,"version"),line!["sequence"]!.GetValue<int>(),"SYNTHETIC-PRIVATE-INSTRUMENT","SYNTHETIC-PRIVATE-RECEIPT-NOTE",DateTimeOffset.UtcNow,true)));var c=received["cheque"]!;cheques.Add(c.DeepClone());if(commit)await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/cheque-approvals/"+V(c,"id")+"/commands/"+Id(),new ChequeApprovalInput("Approve",pi.OrderVersion,V(schedule,"version"),V(c,"version"),null,"Synthetic manual approval prerequisite",DateTimeOffset.UtcNow,true,false)));}
        if(commit){var up=await CreditScheduleQa.Read(await f.GetAsync(path+"/upfront"));var zero=V(up,"requiredAmountRial")=="0";await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/upfront/commands/"+Id(),new CreditUpfrontInput(zero?"ConfirmNoUpfrontDue":"ConfirmReceipt",pi.OrderVersion,V(schedule,"version"),null,zero?"":"SYNTHETIC-NO-FUNDS","Synthetic upfront attestation only",DateTimeOffset.UtcNow,true)));var clearance=await CreditScheduleQa.Read(await f.GetAsync(path+"/clearance"));await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/clearance/commands/"+Id(),new CreditClearanceInput("Approve",V(clearance,"orderVersion"),null,V(clearance,"previewFingerprint"),"Synthetic only; no actual purchase or funds",true)));}return new(s.Customer,s.Owner,order,s.Goods.Variant,summary,cheques.ToArray());
    }
    private static CreditReminderInput Input(JsonNode p)=>new(V(p,"orderVersion"),V(p["cheque"]!,"version"),V(p,"previewFingerprint"),"SYNTHETIC-PRIVATE-REMINDER-REVIEW",true);
    private static async Task<JsonNode> Page(HttpClient f,Scenario s,int index=0)=>await Read(await f.GetAsync(Reminder(s,index)));
    private static async Task<HttpResponseMessage> PostReminder(HttpClient client,string path,CreditReminderInput input){var raw=JsonSerializer.Serialize(input,new JsonSerializerOptions(JsonSerializerDefaults.Web));var request=new HttpRequestMessage(HttpMethod.Post,path){Content=new StringContent(raw,System.Text.Encoding.UTF8,"application/json")};request.Options.Set(new HttpRequestOptionsKey<string>("SyntheticReminderPostedBody"),raw);return await client.SendAsync(request);}
    private static async Task<JsonNode> Send(HttpClient f,Scenario s,JsonNode p,string? command=null)=>await Read(await PostReminder(f,Reminder(s)+"/commands/"+(command??Id()),Input(p)));
    private async Task Counts(int events,int inbox,int audits)
    {
        await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;Assert.Equal(events,await sp.GetRequiredService<CreditDbContext>().ReminderEvents.CountAsync());Assert.Equal(events,await sp.GetRequiredService<CreditDbContext>().ReminderCommands.CountAsync());Assert.Equal(inbox,await sp.GetRequiredService<NotificationsDbContext>().CreditInbox.CountAsync());Assert.Equal(audits,await sp.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Action=="CREDIT_CHEQUE_REMINDER"));Assert.Equal(0,await sp.GetRequiredService<SalesDbContext>().OrderCashPayments.CountAsync());Assert.Equal(0,await sp.GetRequiredService<SalesDbContext>().Orders.CountAsync(x=>x.State==OrderState.Paid));
    }
    [Fact]public async Task OwnedPrivateInboxReplayAndConcurrentReadAcknowledgementsPreserveFinancialFacts()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var p=await Page(f,s);Assert.True(p["canSend"]!.GetValue<bool>());var cmd=Id();var first=await Send(f,s,p,cmd);Assert.Equal(V(p,"orderVersion"),V(first["event"]!["summary"]!,"orderVersion"));Assert.Equal(V(p,"previewFingerprint"),V(first["event"]!["summary"]!,"previewFingerprint"));var repeat=await Send(f,s,p,cmd);Assert.True(repeat["replayed"]!.GetValue<bool>());Assert.Equal(first["event"]!.ToJsonString(),repeat["event"]!.ToJsonString());var receipt=await Read(await f.GetAsync(Reminder(s)+"/commands/"+cmd));Assert.True(receipt["replayed"]!.GetValue<bool>());var current=await Page(f,s);Assert.False(current["canSend"]!.GetValue<bool>());Assert.NotNull(current["sentToday"]);var inbox=await Read(await customer.GetAsync("/api/notifications/credit-reminders?unreadOnly=true"));var item=Assert.Single(inbox["items"]!.AsArray())!;Assert.Equal(V(s.Cheques[0],"amountRial"),V(item,"amountRial"));Assert.Equal(V(s.Cheques[0],"dueDate"),V(item,"dueDate"));Assert.Equal(s.Order,V(item,"orderId"));Assert.DoesNotContain("SYNTHETIC-PRIVATE",inbox.ToJsonString());Assert.DoesNotContain("instrumentReference",inbox.ToJsonString());Assert.DoesNotContain("actorId",inbox.ToJsonString());Assert.Equal("1",V(await Read(await customer.GetAsync("/api/notifications/credit-reminders/unread-count")),"unreadCount"));var marks=await Task.WhenAll(customer.PutAsJsonAsync("/api/notifications/credit-reminders/"+V(item,"id")+"/read",new{}),customer.PutAsJsonAsync("/api/notifications/credit-reminders/"+V(item,"id")+"/read",new{}));var marked=await Task.WhenAll(marks.Select(Read));Assert.Equal(marked[0]["notification"]!["readAt"]!.ToJsonString(),marked[1]["notification"]!["readAt"]!.ToJsonString());Assert.Empty((await Read(await customer.GetAsync("/api/notifications/credit-reminders?unreadOnly=true")))["items"]!.AsArray());Assert.Equal("0",V(await Read(await customer.GetAsync("/api/notifications/credit-reminders/unread-count")),"unreadCount"));var stranger=await Customer();using(var other=stranger.Client){Assert.Empty((await Read(await other.GetAsync("/api/notifications/credit-reminders")))["items"]!.AsArray());using var denied=await other.PutAsJsonAsync("/api/notifications/credit-reminders/"+V(item,"id")+"/read",new{});Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);}await Counts(1,1,1);await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(OrderState.CreditApproved,(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.SingleAsync(x=>x.Id==s.Order)).State);Assert.Equal(1,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant)).Reserved);Assert.Equal(6,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().ReceivedCheques.CountAsync());Assert.Equal(6,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().ChequeLedgerEvents.CountAsync());
    }
    private sealed class RefusingWriter:ICreditReminderNotificationWriter{public Task RecordAsync(CreditReminderNotificationEvent value,CancellationToken ct)=>throw new BusinessException("notification_unavailable","Synthetic rollback exercise.");}
    private static HttpClient CopyClient(WebApplicationFactory<Program> factory,HttpClient source){var c=factory.CreateClient(new(){HandleCookies=false});foreach(var h in source.DefaultRequestHeaders)c.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);return c;}
    [Fact]public async Task NotificationOrAuditFailureRollsBackAndTwoCommandsCannotSendTwiceInOneDay()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var p=await Page(f,s);var command=Id();var path=Reminder(s)+"/commands/"+command;await using(var bad=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddScoped<ICreditReminderNotificationWriter,RefusingWriter>()))){using var client=CopyClient(bad,f);using var refused=await client.PostAsJsonAsync(path,Input(p));Assert.Equal(HttpStatusCode.ServiceUnavailable,refused.StatusCode);}await Counts(0,0,0);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_ReminderAudit CHECK ([Action]<>'CREDIT_CHEQUE_REMINDER')");try{using var failed=await f.PostAsJsonAsync(path,Input(p));Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_ReminderAudit");}await Counts(0,0,0);var race=await Task.WhenAll(PostReminder(f,path,Input(p)),PostReminder(f,Reminder(s)+"/commands/"+Id(),Input(p)));Assert.Single(race,x=>x.IsSuccessStatusCode);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();await Counts(1,1,1);
    }
    private sealed class FixedClock(DateTimeOffset now):TimeProvider{public override DateTimeOffset GetUtcNow()=>now;}
    [Fact]public async Task LedgerVersionAndCivilDayAreRecheckedWhileOriginalReceiptRemainsRecoverable()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var old=await Page(f,s);var c=s.Cheques[0];var moved=await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(c,"id")+"/commands/"+Id(),new MoveChequeInput(V(c,"version"),"Deposit","Synthetic ledger change before notice",DateTimeOffset.UtcNow,true,true)));using(var stale=await f.PostAsJsonAsync(Reminder(s)+"/commands/"+Id(),Input(old)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var p=await Page(f,s);Assert.True(p["canSend"]!.GetValue<bool>());var cmd=Id();var first=await Send(f,s,p,cmd);Assert.Equal("Deposited",V(first["event"]!["summary"]!,"ledgerState"));var tomorrow=DateTimeOffset.UtcNow.AddDays(1);await using(var future=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new FixedClock(tomorrow))))){using var client=CopyClient(future,f);using(var stale=await client.PostAsJsonAsync(Reminder(s)+"/commands/"+Id(),Input(p)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var next=await Send(client,s,await Page(client,s));Assert.Equal(2,next["event"]!["summary"]!["sequence"]!.GetValue<int>());var replay=await Send(client,s,p,cmd);Assert.Equal(first["event"]!.ToJsonString(),replay["event"]!.ToJsonString());Assert.True(replay["replayed"]!.GetValue<bool>());}Assert.False((await Page(f,s))["canSend"]!.GetValue<bool>());await Counts(2,2,2);await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(c,"id")+"/commands/"+Id(),new MoveChequeInput(V(moved["cheque"]!,"version"),"ReportCollection","Synthetic collection report only",DateTimeOffset.UtcNow,true,true)));Assert.False((await Page(f,s))["canSend"]!.GetValue<bool>());
    }
    [Fact]public async Task UncommittedCancelledReturnedAndForeignRoleOrForgedFieldsCannotSend()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Ready(f,reviewer,false);using var customer=s.Customer;var p=await Page(f,s);Assert.False(p["canSend"]!.GetValue<bool>());using(var denied=await f.PostAsJsonAsync(Reminder(s)+"/commands/"+Id(),Input(p)))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);await CreditOrderQa.Read(await customer.PostAsJsonAsync("/api/orders/v2/"+s.Order+"/cancel",new{version=V(s.OrderSummary,"version")}));Assert.False((await Page(f,s))["canSend"]!.GetValue<bool>());foreach(var deniedClient in new[]{reviewer,sales,customer}){using var denied=await deniedClient.GetAsync(Reminder(s));Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}var ready=await Ready(f,reviewer);using var owner=ready.Customer;var page=await Page(f,ready);var forged=JsonSerializer.SerializeToNode(Input(page),new JsonSerializerOptions(JsonSerializerDefaults.Web))!.AsObject();forged["amountRial"]="1";using(var invalid=await f.PostAsJsonAsync(Reminder(ready)+"/commands/"+Id(),forged))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);using(var badQuery=await f.GetAsync(Reminder(ready)+"/history?beforeSequence=01"))Assert.Equal(HttpStatusCode.BadRequest,badQuery.StatusCode);var c=ready.Cheques[0];await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(ready)+"/cheques/"+V(c,"id")+"/commands/"+Id(),new MoveChequeInput(V(c,"version"),"ReturnToCustomer","Synthetic instrument returned",DateTimeOffset.UtcNow,true,true)));Assert.False((await Page(f,ready))["canSend"]!.GetValue<bool>());await Counts(0,0,0);
    }
    [Fact]public async Task CiphertextTamperImmutableGuardsAndMigrationDownCannotLoseReminderHistory()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var sent=await Send(f,s,await Page(f,s));var id=V(sent["event"]!["summary"]!,"id");await using var scope=sql.Factory.Services.CreateAsyncScope();var credit=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var notifications=scope.ServiceProvider.GetRequiredService<NotificationsDbContext>();Assert.False(credit.Database.HasPendingModelChanges());Assert.False(notifications.Database.HasPendingModelChanges());var down=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>credit.GetService<IMigrator>().MigrateAsync("20261028002335_ChequeDueReportIndex"));Assert.Equal(51000,down.Number);var allInboxMigrations=notifications.Database.GetMigrations().ToArray();var reminderMigration=Array.FindIndex(allInboxMigrations,x=>x.EndsWith("_PrivateCreditReminderInbox",StringComparison.Ordinal));Assert.True(reminderMigration>0);var assembly=notifications.GetService<IMigrationsAssembly>();var ownMigration=assembly.CreateMigration(assembly.Migrations[allInboxMigrations[reminderMigration]],notifications.Database.ProviderName!);var ownGuard=Assert.IsType<Microsoft.EntityFrameworkCore.Migrations.Operations.SqlOperation>(ownMigration.DownOperations[0]);var inboxDown=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>notifications.Database.ExecuteSqlRawAsync(ownGuard.Sql));Assert.Equal(51000,inboxDown.Number);Assert.Equal(allInboxMigrations,await notifications.Database.GetAppliedMigrationsAsync());var e=await credit.ReminderEvents.SingleAsync(x=>x.Id==id);e.ActorId="OTHER";Assert.Equal("credit_reminder_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>credit.SaveChangesAsync())).Code);credit.ChangeTracker.Clear();await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>credit.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ReminderCommands] SET [ChequeId]={Id()} WHERE [EventId]={id}"));await notifications.Database.ExecuteSqlInterpolatedAsync($"UPDATE [notifications].[CreditInbox] SET [ProtectedPayload]={new byte[]{1,2,3}} WHERE [Id]={id}");using(var badInbox=await customer.GetAsync("/api/notifications/credit-reminders"))Assert.Equal(HttpStatusCode.ServiceUnavailable,badInbox.StatusCode);using(var badRead=await customer.PutAsJsonAsync("/api/notifications/credit-reminders/"+id+"/read",new{}))Assert.Equal(HttpStatusCode.ServiceUnavailable,badRead.StatusCode);Assert.Null((await notifications.CreditInbox.AsNoTracking().SingleAsync(x=>x.Id==id)).ReadAt);await credit.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ReminderEvents] SET [ProtectedEvent]={new byte[]{1,2,3}} WHERE [Id]={id}");using(var badHistory=await f.GetAsync(Reminder(s)+"/history"))Assert.Equal(HttpStatusCode.ServiceUnavailable,badHistory.StatusCode);await Counts(1,1,1);
    }
